import React from "react";

export function Comp3dCard2() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>3D Flip Card with Tailwind</title>

  <style>
    .flip-card {
      perspective: 1000px;
    }

    .flip-inner {
      transition: transform 0.8s;
      transform-style: preserve-3d;
    }

    .flipped {
      transform: rotateY(180deg);
    }

    .flip-front, .flip-back {
      backface-visibility: hidden;
      -webkit-backface-visibility: hidden;
    }

    .flip-back {
      transform: rotateY(180deg);
    }
  </style>
</head>
<body class="bg-gradient-to-br from-purple-500 to-indigo-700 min-h-screen flex items-center justify-center">

  <div class="flip-card w-80 h-48">
    <div class="flip-inner relative w-full h-full">
      <!-- Front -->
      <div class="flip-front absolute w-full h-full bg-white text-black flex items-center justify-center rounded-xl shadow-xl text-xl font-bold">
        Click Me (Front)
      </div>
      <!-- Back -->
      <div class="flip-back absolute w-full h-full bg-indigo-600 text-white flex items-center justify-center rounded-xl shadow-xl text-xl font-bold">
        Hello! (Back)
      </div>
    </div>
  </div>



</body>
</html>" }} />
  );
}
